WITH sales AS (SELECT voucher_no,SUM(credit-debit) sales_amount FROM "tabGL Entry" g JOIN "tabAccount" a ON a.name=g.account WHERE g.voucher_type='Sales Invoice' AND a.account_type='Income' AND (%(company)s='' OR g.company=%(company)s) AND (%(from_date)s='' OR g.posting_date>=%(from_date)s) AND (%(to_date)s='' OR g.posting_date<=%(to_date)s) GROUP BY voucher_no), cogs AS (SELECT voucher_no,SUM(debit-credit) cogs_amount FROM "tabGL Entry" g JOIN "tabAccount" a ON a.name=g.account WHERE g.voucher_type='Sales Invoice' AND a.account_type='COGS' AND (%(company)s='' OR g.company=%(company)s) AND (%(from_date)s='' OR g.posting_date>=%(from_date)s) AND (%(to_date)s='' OR g.posting_date<=%(to_date)s) GROUP BY voucher_no) SELECT s.voucher_no,s.sales_amount,COALESCE(c.cogs_amount,0) AS cogs_amount,s.sales_amount-COALESCE(c.cogs_amount,0) AS gross_profit FROM sales s LEFT JOIN cogs c ON c.voucher_no=s.voucher_no ORDER BY s.voucher_no
